package app.rollentrainer.ui.world.geo.race

import app.rollentrainer.ui.world.geo.Anim
import app.rollentrainer.ui.world.geo.SceneMaterial
import app.rollentrainer.ui.world.geo.VariantCells

/*
 * Materials and texture atlas layouts of the race dressing. The textures are generated by
 * scratchpad/b14/w3/tex/gen_race_textures.py into assets/tex (race_flags, race_signs, race_roadpaint);
 * the layouts here must match that script.
 */
object RaceMaterials {
    /** Spectators: vertex colours only; CHEER moves the arms by Vtx.EXTRA (0 shoulder .. 1 hand). */
    val PEOPLE = SceneMaterial("race_people", roughness = 0.85f, anim = Anim.CHEER)

    /**
     * The shared far silhouettes (People.FAR*, beyond 120 m): no shadow. A spectator's shadow is too
     * small to see that far, and the near spectators already cast theirs with their own pose's LODs.
     */
    val PEOPLE_FAR = PEOPLE.copy(key = "race_people_far", castsShadow = false)

    /** Spectators' sunglasses: a little gloss, no shadow (a few centimetres of plastic). */
    val PEOPLE_GLASSES = PEOPLE.copy(key = "race_people_glasses", roughness = 0.3f, castsShadow = false)

    /**
     * Flags: the mesh UVs address atlas cell 0; the renderer adds the cell offset of the instance's
     * variant: uv += vec2(variant mod 8, floor(variant / 8)) / vec2(8, 4) (W1's object shader). FLAG
     * waves the cloth by Vtx.EXTRA = metres from the pole.
     */
    val FLAG = SceneMaterial("race_flag", texture = "race_flags", doubleSided = true, roughness = 0.75f, anim = Anim.FLAG)

    /** Banners, arches, boards (UVs into race_signs, 0..1 over the whole atlas). */
    val SIGNS = SceneMaterial("race_signs", texture = "race_signs", roughness = 0.7f)

    /**
     * Barrier covers: the same atlas, the mesh UVs address cover 0 and the instance variant picks the
     * cover (the renderer adds (variant mod 4, floor(variant / 4)) cells of 512 x 256 px, see
     * Atlas.cover), so all printed barriers are one prototype and one draw.
     */
    val SIGNS_COVERS = SIGNS.copy(key = "race_signs_covers", variantCells = VariantCells(Atlas.COVER_COLS, Atlas.COVER_CELL_U, Atlas.COVER_CELL_V))

    /** Painted words on the asphalt: alpha cut out, drawn with polygon offset, no shadow. */
    val ROAD_PAINT = SceneMaterial("race_roadpaint", texture = "race_roadpaint", alphaCutout = true, roughness = 0.5f, castsShadow = false, decal = true)

    /** Painted steel, plastic, car bodies: vertex colours. */
    val PROPS = SceneMaterial("race_props", roughness = 0.55f)

    /** Glossy parts: glass, chrome, car paint highlights. */
    val GLOSS = SceneMaterial("race_gloss", roughness = 0.18f)

    /** Finish and sprint lines on the asphalt: vertex colours, no shadow (it lies 2 cm above the road). */
    val LINE = SceneMaterial("race_line", roughness = 0.5f, castsShadow = false, decal = true)

    /** Tents, awnings, banners without print: thin cloth seen from both sides. */
    val CLOTH = SceneMaterial("race_cloth", doubleSided = true, roughness = 0.9f)
}

object Atlas {
    // --- race_flags: 8 x 4 cells (128 px), flags 3:2 squeezed into square cells -----------------
    const val FLAG_COLS = 8
    const val FLAG_ROWS = 4
    /** Cell index = InstanceSet.variant of a flag instance. */
    val FLAGS = listOf(
        "FR", "ES", "CAT", "EUS", "BZH", "BE", "VLA", "NL",
        "DK", "NO", "SI", "CO", "DE", "IT", "GB", "CH",
        "LU", "AT", "IE", "PT", "US", "AU", "ER", "CZ",
        "PL", "CA", "SAV", "OCC", "KOM", "YEL", "ORA", "ALLEZ",
    )
    fun flag(code: String): Int = FLAGS.indexOf(code).also { require(it >= 0) { code } }
    /** UV rectangle of cell 0 with a texel of margin against bleeding at lower mip levels. */
    const val FLAG_U0 = 1.5f / 1024f
    const val FLAG_U1 = 1f / FLAG_COLS - 1.5f / 1024f
    const val FLAG_V0 = 1.5f / 512f
    const val FLAG_V1 = 1f / FLAG_ROWS - 1.5f / 512f

    // --- race_signs: 24 banner cells (1024 x 128, 2 columns), 8 barrier covers (512 x 256) --------
    const val ARRIVEE = 0
    const val DEPART = 1
    const val SPRINT = 2
    const val GPM = 3
    /** "25 km", "20 km", "15 km", "10 km", "5 km", "4 km", "3 km", "2 km". */
    val KM_BANNERS = mapOf(25 to 4, 20 to 5, 15 to 6, 10 to 7, 5 to 8, 4 to 9, 3 to 10, 2 to 11)
    const val DERNIER_KM = 12
    const val BRAND = 13
    const val ALLEZ = 14
    const val CLOCK = 15
    /** Distance boards in the final kilometre: metres to go → cell (the board uses the cell's middle quarter). */
    val BOARDS = mapOf(500 to 16, 300 to 17, 200 to 18, 150 to 19, 100 to 20, 50 to 21)
    const val ARRIVEE_RED = 22
    const val BIENVENUE = 23

    class Rect(val u0: Float, val v0: Float, val u1: Float, val v1: Float)

    fun banner(cell: Int, inset: Float = 1.5f): Rect {
        val x = (cell % 2) * 1024f
        val y = (cell / 2) * 128f
        return Rect((x + inset) / 2048f, (y + inset) / 2048f, (x + 1024f - inset) / 2048f, (y + 128f - inset) / 2048f)
    }

    /** The middle quarter of a banner cell (clock face, distance boards: 2:1 panels). */
    fun bannerMiddle(cell: Int): Rect {
        val r = banner(cell)
        val w = r.u1 - r.u0
        return Rect(r.u0 + w * 0.375f, r.v0, r.u0 + w * 0.625f, r.v1)
    }

    const val COVER_COLS = 4
    const val COVER_CELL_U = 512f / 2048f
    const val COVER_CELL_V = 256f / 2048f
    const val COVERS = 8

    /** Barrier covers: 0 WATTWERK blue, 1 SPRINT green, 2 polka dots, 3 ALLEZ yellow, 4 BRAVO tricolour, 5 COURAGE red, 6 ARRIVÉE navy, 7 chequered. */
    fun cover(i: Int, inset: Float = 1.5f): Rect {
        val x = (i % COVER_COLS) * 512f
        val y = 1536f + (i / COVER_COLS) * 256f
        return Rect((x + inset) / 2048f, (y + inset) / 2048f, (x + 512f - inset) / 2048f, (y + 256f - inset) / 2048f)
    }

    // --- race_roadpaint: 16 cells (512 x 128), 2 columns --------------------------------------------
    val WORDS = listOf(
        "ALLEZ", "VAS-Y", "ALLEZ KILI", "AUPA", "FORZA", "HOP HOP", "COURAGE", "BRAVO",
        "GO GO GO", "ALLEZ ALLEZ", "<hearts>", "<stars>", "<chevrons>", "KILI", "HUP", "VAMOS",
    )
    fun word(w: String): Int = WORDS.indexOf(w).also { require(it >= 0) { w } }

    fun paint(cell: Int, inset: Float = 1f): Rect {
        val x = (cell % 2) * 512f
        val y = (cell / 2) * 128f
        return Rect((x + inset) / 1024f, (y + inset) / 1024f, (x + 512f - inset) / 1024f, (y + 128f - inset) / 1024f)
    }
}
